-- 0004_w5_room_save_archives. Archive of room saves written for another terrain bake (owner decision 2026-11-16): the
-- server moves the live rows here verbatim and starts a fresh room; nothing is ever deleted, a restore is the reverse copy.
-- Generated by drizzle-kit, then amended by hand BEFORE merge in two ways (same two amendments as 0001 and 0003):
--   1. the foreign-key targets are not qualified with the "public" schema, so the migration follows search_path
--      (prod | staging | _aN); migrate.test.ts fails the build if a migration mentions it.
--   2. the trailing ALTERs set blob to EXTERNAL storage: the payloads are already deflate-compressed, so PostgreSQL must
--      not spend CPU trying to pglz them again.
-- Expand step only: two new tables, so code from before this migration keeps working. Indexes: the one on
-- contract_save_archives(contract_id, archived_at desc) serves "archives of this Contract, newest first" (support
-- recovery; the primary key leads with archive_id, so it cannot). The chunk archive has no secondary index: it is read
-- only through (archive_id), the leading column of its primary key. Rows are at most the size of the live save they came
-- from (storage is not duplicated: the live rows are deleted in the same transaction). Forward-only; never edit after merge.
CREATE TABLE "contract_dust_chunk_archives" (
	"archive_id" uuid NOT NULL,
	"contract_id" uuid NOT NULL,
	"chunk_id" smallint NOT NULL,
	"ver" smallint NOT NULL,
	"save_seq" bigint NOT NULL,
	"codec" text NOT NULL,
	"raw_size" integer NOT NULL,
	"blob_size" integer NOT NULL,
	"checksum" integer NOT NULL,
	"blob" "bytea" NOT NULL,
	"saved_at" timestamp with time zone NOT NULL,
	CONSTRAINT "contract_dust_chunk_archives_pk" PRIMARY KEY("archive_id","chunk_id","ver"),
	CONSTRAINT "contract_dust_chunk_archives_chunk_id_check" CHECK ("contract_dust_chunk_archives"."chunk_id" between 0 and 640),
	CONSTRAINT "contract_dust_chunk_archives_ver_check" CHECK ("contract_dust_chunk_archives"."ver" in (0, 1))
);
